import{_ as t,o,c as n,a2 as a}from"./chunks/framework.BXzK3EA4.js";const s="/assets/d072a5f441c77950.ChUlspLc.png",i="/assets/61890193282c5b73.Myr22-5y.png",r="data:image/png;base64,",l="/assets/1307497af14e0233.BwuTnARw.png",p="/assets/53f68973223c24ac.Cg3owdaF.png",c="/assets/16312710f0f53574.CsFJxJMi.png",d="/assets/e70cc480cced8646.BwlO3X6P.png",T=JSON.parse('{"title":"How to remotely access a Linux system using Putty tool","description":"","frontmatter":{"title":"How to remotely access a Linux system using Putty tool"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/linux/how-to-remotely-access-a-linux-system-using-putty-tool.md","filePath":"operations-knowledge-base/operating-system/linux/how-to-remotely-access-a-linux-system-using-putty-tool.md","lastUpdated":1794311093000}'),m={name:"operations-knowledge-base/operating-system/linux/how-to-remotely-access-a-linux-system-using-putty-tool.md"};function u(w,e,h,g,f,A){return o(),n("div",null,[...e[0]||(e[0]=[a('<p>Introduction to Putty software</p><p>PuTTY is a Telnet, SSH, rlogin, raw TCP, and serial interface connection software. Earlier versions of PuTTY were only available for the Windows platform, but recent versions have started to support various Unix platforms and are planned to be ported to Mac OS X. In addition to the official version, there are many third-party groups or individuals who have ported PuTTY to other platforms, such as Symbian-based mobile phones. PuTTY is an open-source software primarily maintained by Simon Tatham and is licensed under the MIT license. With the increasing popularity of Linux in server-side applications, remote management of Linux systems heavily relies on remote login tools. Among various remote login tools, PuTTY stands out as an excellent option. PuTTY is a free Telnet, SSH, and rlogin client for Windows x86 platform, offering features comparable to commercial Telnet clients.</p><p>Download link：<a href="https://www.chiark.greenend.org.uk/~sgtatham/putty/" target="_blank" rel="noreferrer">PuTTY: A Free SSH and Telnet Client (greenend.org.uk)</a></p><p><img src="'+s+'" alt=""></p><p>Click on the red arrow in the image above to initiate the download. You will be redirected to the following interface. Choose the appropriate link for your system and click on it to start the download.</p><p><img src="'+i+'" alt=""></p><p>Click on the red arrow in the image above to initiate the download. After the download and installation are completed, the icon will appear as shown in the image below：</p><p><img src="'+r+'" alt=""></p><p>1.The connection steps are as follows:</p><ul><li><p>Enter the instance IP address.</p></li><li><p>Enter the remote port number for the instance. The default port number for Linux is 22, but the image below shows a randomly set port number.</p></li><li><p>Select the connection type as SSH.</p></li><li><p>Click &quot;Open&quot; to initiate the connection.</p></li></ul><p><img src="'+l+'" alt=""></p><ul><li>Click &quot;Accept&quot;.</li></ul><p><img src="'+p+'" alt=""></p><p>2.Enter your username and password. The password will not be displayed, but you can copy and paste it.</p><p><img src="'+c+'" alt=""></p><p>3.Successfully connected to the instance as shown in the following image.</p><p><img src="'+d+'" alt=""></p>',17)])])}const v=t(m,[["render",u]]);export{T as __pageData,v as default};
